        row = self.store.invoice(invoice_id)
        return {"invoice_id": invoice_id, "state": row["state"], "outcome": outcome,
                "charge_id": row.get("charge_id")}

    def submit(self, invoice_id: str) -> dict:
        store = self.store
        invoice = store.invoice(invoice_id)
        if invoice_id not in store.due():
            return self._result(invoice_id, "skipped")
        merchant_id = invoice["merchant_id"]
        # Never charge without first checking the provider for an existing charge of this invoice.
        charges = invoice_charges(store, self.provider, invoice)
        if charges is None:
            return self._result(invoice_id, "deferred")
        live = live_charges(charges)
        if live:
            store.mark_paid(invoice_id, live[0]["charge_id"])
            return self._result(invoice_id, "reconciled")
        counter = run_counter(store)
        if (not provider_allowed(store, merchant_id)
                or counter.get(invoice_id, 0) >= MAX_CHARGE_REQUESTS_PER_INVOICE):
            return self._result(invoice_id, "deferred")
        counter[invoice_id] = counter.get(invoice_id, 0) + 1
        key = payment_key(invoice, key_generation(store, invoice, charges))
        attempt = store.next_attempt(invoice_id)
        charge_id = None
        try:
            result = self.provider.charge(
                key,
                merchant_id=merchant_id,
                invoice_id=invoice_id,
                subscription_id=invoice["subscription_id"],
                period=invoice["period"],
                amount=invoice["amount"],
            )
        except ProviderTimeout:
            note_request(store, merchant_id)
            outcome, state = "timeout", "retry"
        except ProviderError as exc:
            code = getattr(exc, "code", None) or "provider_error"
            note_request(store, merchant_id, rate_limited=(code == "rate_limited"))
            outcome, state = code, "retry"
        else:
            note_request(store, merchant_id)
            if result.get("status") == "succeeded":
                outcome, state, charge_id = "succeeded", "paid", result["charge_id"]
                add_ledger_charge(store, invoice, charge_id, key)
            else:
                outcome, state = "declined", "failed"
        store.record_attempt(invoice_id, attempt=attempt, key=key, outcome=outcome, charge_id=charge_id,
                             payment_method_updated_at=invoice.get("payment_method_updated_at"))
        if state == "paid":
            store.mark_paid(invoice_id, charge_id)
        else:
            store.mark(invoice_id, state)
        return {"invoice_id": invoice_id, "state": state, "outcome": outcome, "charge_id": charge_id}
