from .reconcile import RELEASED_STATE, begin_run, invoice_charges, refund_term, sync_invoice
from .store import BillingStore


def _apply_blind(store: BillingStore, event: dict) -> None:
    """Fallback when the provider ledger cannot be read: apply the event conservatively."""
    invoice_id = event["invoice_id"]
    row = store.invoice(invoice_id)
    if event["type"] == "charge.succeeded":
        if row["state"] in store.DUE_STATES:
            store.mark_paid(invoice_id, event["charge_id"])
    elif event["type"] == "charge.refunded":
        if row["state"] == "paid" and row.get("charge_id") == event["charge_id"]:
            term = refund_term(row["merchant_id"])
            store.payment_refunded(invoice_id, RELEASED_STATE if term == "release" else "retry")


def apply_webhook_events(store: BillingStore, events: list[dict], provider) -> int:
    """Apply provider events (charge.succeeded / charge.refunded) to invoice rows.

    Events may be stale or out of order, so each touched invoice is settled against
    the provider's current records rather than the event payload.
    """
    begin_run(store)
    applied = 0
    for event in events or []:
        invoice_id = event.get("invoice_id")
        if invoice_id not in store.invoices:
            continue
        if event.get("type") not in ("charge.succeeded", "charge.refunded"):
            continue
        row = store.invoice(invoice_id)
        charges = invoice_charges(store, provider, row)
        if charges is None:
            _apply_blind(store, event)
        else:
            sync_invoice(store, invoice_id, charges)
        applied += 1
    return applied
