    except ProviderTimeout:
        note_request(store, merchant_id)
        return None
    except ProviderError as exc:
        note_request(store, merchant_id, rate_limited=getattr(exc, "code", None) == "rate_limited")
        return None
    note_request(store, merchant_id)
    st["ledger"][merchant_id] = [dict(r) for r in (records or [])]
    return st["ledger"][merchant_id]


def invoice_charges(store: BillingStore, provider, invoice: dict):
    records = merchant_ledger(store, provider, invoice["merchant_id"])
    if records is None:
        return None
    found = [r for r in records
             if r.get("invoice_id") == invoice["invoice_id"]
             and r.get("period", invoice.get("period")) == invoice.get("period")]
    return sorted(found, key=lambda r: (r.get("created_at") is None, r.get("created_at") or 0))


def live_charges(charges: list[dict]) -> list[dict]:
    return [c for c in charges if c.get("status") == "succeeded"]


def add_ledger_charge(store: BillingStore, invoice: dict, charge_id: str, key: str) -> None:
    records = _run_state(store)["ledger"].get(invoice["merchant_id"])
    if records is None or any(r.get("charge_id") == charge_id for r in records):
        return
    records.append({"charge_id": charge_id, "invoice_id": invoice["invoice_id"],
                    "subscription_id": invoice.get("subscription_id"), "period": invoice.get("period"),
                    "amount": invoice.get("amount"), "status": "succeeded", "refunded_at": None,
                    "idempotency_key": key, "created_at": None})


def key_generation(store: BillingStore, invoice: dict, charges: list[dict]) -> int:
    prefix = payment_key(invoice, 0).rsplit(":", 1)[0] + ":"
    generation = 0
    for attempt in store.attempts_for(invoice["invoice_id"]):
        outcome = attempt.get("outcome")
        if outcome == "declined":
            generation += 1
        elif outcome == "idempotency_conflict" and str(attempt.get("key", "")).startswith(prefix):
            generation += 1
    generation += sum(1 for c in charges if c.get("status") == "refunded")
    return generation


def sync_invoice(store: BillingStore, invoice_id: str, charges: list[dict]):
    """Bring one invoice row in line with the provider's records."""
    row = store.invoice(invoice_id)
    state = row["state"]
    live = live_charges(charges)
    if state == "paid":
        if any(c.get("charge_id") == row.get("charge_id") for c in live):
            return None
        if live:
            store.mark_paid(invoice_id, live[0]["charge_id"])
            return "paid"
        recorded = next((c for c in charges if c.get("charge_id") == row.get("charge_id")), None)
        if recorded is not None and recorded.get("status") == "refunded":
            if refund_term(row["merchant_id"]) == "release":
                store.payment_refunded(invoice_id, RELEASED_STATE)
                return RELEASED_STATE
            store.payment_refunded(invoice_id, "retry")
            return "retry"
        return None
    if state in ("pending", "retry", "failed") and live:
        store.mark_paid(invoice_id, live[0]["charge_id"])
        return "paid"
    return None


def reconcile_pending(store: BillingStore, provider) -> list[dict]:
    """Settle due invoices that already have a live provider charge (matched by invoice)."""
    changes = []
    for invoice_id in store.due():
        invoice = store.invoice(invoice_id)
        charges = invoice_charges(store, provider, invoice)
        if not charges:
            continue
        live = live_charges(charges)
        if live:
            store.mark_paid(invoice_id, live[0]["charge_id"])
            changes.append({"invoice_id": invoice_id, "charge_id": live[0]["charge_id"]})
    return changes
